&lt;ul&gt;
&lt;li class=&quot;&quot;&gt;&lt;span class=&quot;ql-author-10000003316 ql-size-12 ql-font-arial&quot;&gt;PhD or internship experience related to robotics planning system designs&lt;/span&gt;&lt;span class=&quot;ql-author-10000202573 ql-size-12 ql-font-arial&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;&quot;&gt;&lt;span class=&quot;ql-author-10000202573 ql-size-12 ql-font-arial&quot;&gt;Knowledge of vehicle dynamics and longitudinal/lateral control systems.&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;&quot;&gt;&lt;span class=&quot;ql-author-10000202573 ql-size-12 ql-font-arial&quot;&gt;Solid understanding&amp;nbsp;of machine learning principles&lt;/span&gt;&lt;span class=&quot;ql-author-10000003316 ql-size-12 ql-font-arial&quot;&gt;, reinforcement learning&lt;/span&gt;&lt;span class=&quot;ql-author-10000202573 ql-size-12 ql-font-arial&quot;&gt; and &lt;/span&gt;&lt;span class=&quot;ql-author-10000003316 ql-size-12 ql-font-arial&quot;&gt;related &lt;/span&gt;&lt;span class=&quot;ql-author-10000202573 ql-size-12 ql-font-arial&quot;&gt;algorithms.&lt;/span&gt;&lt;/li&gt;
